  className,
}: {
  data: SleepRecoveryTrendPoint[]
  className?: string
}) {
  const reactId = useId().replace(/:/g, '')
  const sleepGradientId = `sleep-trend-fill-${reactId}`

  return (
    <article
      className={cn(
        'flex min-h-110 flex-col gap-5 rounded-2xl border bg-background p-4 md:p-6',
        className,
